{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-04",
  "sketch": {
    "components": ["Nightly backup job", "Production database", "Restore process"],
    "dataStores": ["Production database", "Cloud storage backup bucket"],
    "externalServices": ["Cloud storage provider"],
    "trustBoundaries": ["Database to cloud storage bucket", "Backup bucket to reporting team"],
    "dataClasses": ["pii", "credentials", "secrets"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Reporting team can read the whole production database from unencrypted backups",
      "scenario": "Anyone with access to the shared bucket, including every member of the reporting team and anyone who compromises one of their accounts, can download a nightly backup and open it directly because nothing is encrypted. A full database dump typically contains all customer records and any secrets or credential hashes stored in the database, so one low-effort download yields the entire dataset with no need to touch production.",
      "component": "Cloud storage backup bucket",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "The backup files are not encrypted." },
        { "quote": "The bucket is shared with the reporting team." }
      ],
      "cwe": ["CWE-311", "CWE-530"],
      "plainLanguage": "The nightly copy of the whole database sits in a shared folder that anyone on the reporting team can open and read.",
      "requirement": {
        "title": "Encrypt database backups and restrict the bucket to the backup and restore roles",
        "given": "a nightly database backup is written to cloud storage",
        "when": "the backup file is created and stored",
        "then": "it is encrypted with a key the reporting team cannot access, and read access to the backup objects is granted only to the backup and restore service identities"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Backup bucket sharing hands reporting-team access over production data it is not authorised to see",
      "scenario": "The bucket is used both as a backup target and as a data-sharing location for reporting. A reporting user who is only entitled to aggregated or scoped reporting data gets, through bucket membership, read access to the complete production dataset including tables and columns outside their authorisation. An attacker who phishes any reporting account inherits that production-wide access without ever obtaining a database credential.",
      "component": "Backup bucket access control",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "The bucket is shared with the reporting team." }
      ],
      "cwe": ["CWE-732", "CWE-1220"],
      "plainLanguage": "Sharing the backup folder with reporting quietly gives them more data access than their normal reporting permissions allow.",
      "requirement": {
        "title": "Separate backup storage from reporting data sharing",
        "given": "the reporting team needs data extracts",
        "when": "reporting access is provisioned",
        "then": "reporting reads from a separate bucket or dataset containing only the fields they are authorised for, and has no permission on the backup bucket"
      }
    },
    {
      "stride": "Tampering",
      "title": "Someone with bucket write access can modify a backup and poison the restored database",
      "scenario": "The backups are plain, unencrypted files in a bucket shared beyond the backup job. Anyone with write access, or an attacker using a stolen reporting credential, can alter rows inside a backup file or replace it entirely. Because there is no stated integrity check, the next restore or disaster-recovery exercise loads the attacker's content into production: injected admin users, changed balances, or deleted records, all appearing to come from a legitimate backup.",
      "component": "Nightly backup files / restore process",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Database backups are written nightly to a cloud storage bucket." },
        { "quote": "The backup files are not encrypted." }
      ],
      "cwe": ["CWE-345", "CWE-494"],
      "plainLanguage": "A backup file could be edited or swapped, and nobody would notice until that bad copy was restored into the live database.",
      "requirement": {
        "title": "Verify backup integrity before restore",
        "given": "a backup file is selected for restore",
        "when": "the restore process reads the file",
        "then": "a cryptographic checksum or signature recorded at backup time is verified, and the restore aborts on mismatch"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Deleting or overwriting backups removes the ability to recover",
      "scenario": "Write and delete rights on the bucket extend past the backup job itself. A ransomware operator or a disgruntled insider using a reporting-team or CI credential can delete every backup object, or overwrite each nightly file with junk so the only remaining copies are useless. The organisation then has no recovery point when the production database fails or is encrypted, turning a recoverable incident into permanent data loss.",
      "component": "Cloud storage backup bucket",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Database backups are written nightly to a cloud storage bucket." },
        { "quote": "The bucket is shared with the reporting team." }
      ],
      "cwe": ["CWE-732"],
      "plainLanguage": "If someone wipes the shared backup folder, there is nothing left to restore from.",
      "requirement": {
        "title": "Make backup objects immutable for their retention period",
        "given": "a backup object has been written to the bucket",
        "when": "any identity attempts to delete or overwrite it before the retention period expires",
        "then": "the operation is denied by object versioning and an immutability or object-lock policy, and no human role holds delete permission"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "A single bucket misconfiguration exposes the full database publicly",
      "scenario": "Because the bucket is already shared with a group rather than locked to the backup identity, its policy is edited by people over time. One over-broad grant, such as making it readable to all authenticated or anonymous users, exposes unencrypted full database dumps to the internet. Attackers routinely scan cloud storage for exactly this, and with no encryption there is no second layer to stop them reading the data once the listing is found.",
      "component": "Cloud storage bucket policy",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "The bucket is shared with the reporting team." },
        { "quote": "The backup files are not encrypted." }
      ],
      "cwe": ["CWE-16", "CWE-284"],
      "plainLanguage": "One wrong sharing setting on that folder would put the entire database online for anyone to download.",
      "requirement": {
        "title": "Block public access and continuously check the backup bucket policy",
        "given": "the backup bucket exists",
        "when": "its access policy is created or changed",
        "then": "account-level public access blocking is enforced and an automated check fails the build or raises an alert if the policy grants access to any principal outside the approved backup and restore roles"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No way to tell which reporting user copied a backup",
      "scenario": "The bucket is shared with a team, so many identities can read the same unencrypted dumps. Without per-object access records tied to individual principals, an exfiltration of customer data cannot be attributed: every member can plausibly deny downloading it, and the organisation cannot determine the scope of a breach or meet notification obligations. This is called out because the design's whole exposure rests on who read these files.",
      "component": "Backup bucket access records",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "The bucket is shared with the reporting team." }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "If a database backup leaks, there is no record showing which person downloaded it.",
      "requirement": {
        "title": "Record per-identity reads of backup objects",
        "given": "an identity reads or lists a backup object",
        "when": "the access occurs",
        "then": "a tamper-resistant record of the identity, object and timestamp is written to a store the reporting team cannot modify, and is retained for the backup retention period"
      }
    }
  ]
}
